import type { ComponentProps as PlaygroundComponentProps } from "react"
import { Field, FieldContent, FieldLabel } from "@/components/ui/field";

import { Input } from "@/components/ui/input";

const playgroundProps: Partial<PlaygroundComponentProps<typeof Field>> = /*__DS_PROPS__*/ {}


export function FieldDemo() {
  return (
    <Field className="w-full max-w-sm">{playgroundProps.children ?? <>
      <FieldLabel htmlFor="username">Username</FieldLabel>
      <FieldContent>
        <Input id="username" placeholder="johndoe" />
      </FieldContent>
    </>}</Field>
  )
}

